function cv3Case(el){
  var tx=el.textContent;if(!/\p{L}/u.test(tx)||tx!==tx.toUpperCase())return;
  var w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),n,start=true;
  while((n=w.nextNode())){
    var s=n.nodeValue.toLowerCase(),o="";
    for(var i=0;i<s.length;i++){var c=s[i];
      if(start&&/[\p{L}\p{N}]/u.test(c)){o+=c.toUpperCase();start=false;}
      else{o+=c;if(/[.!?]/.test(c))start=true;}
    }
    CV3_KEEP.forEach(function(k){o=o.replace(new RegExp("(^|[^\\p{L}])("+k[0]+")(?=[^\\p{L}]|$)","giu"),function(m,a){return a+k[1];});});
    n.nodeValue=o;
  }
}

