    if(d.due)h+='<div class="cv3-qr"><div class="cv3-qr-box">'+cv3Qr(d.id,d.due)+'</div><div><div class="cv3-qr-amt">'+cv3Fmt(d.due)+'</div><div class="cv3-qr-note">'+cv3T(DC.x("course.drawer.j63",0,"Quét QR bằng app ngân hàng hoặc MoMo. Nội dung chuyển khoản: "),DC.x("course.drawer.j63",1,"Scan with your banking or MoMo app. Transfer note: "))+'<b>'+d.id+'</b></div><div class="cv3-qr-demo">'+cv3T(DC.x("course.drawer.j64",0,"QR minh họa — sẽ thay bằng VietQR thật của phòng tập."),DC.x("course.drawer.j64",1,"Demo QR — to be replaced with the gym's real VietQR."))+'</div></div></div>';
    h+='<a class="cv3-zalo" href="'+CV3_ZALO+'" target="_blank" rel="noopener">'+cv3T(DC.x("course.drawer.j65",0,"Nhắn Zalo để xác nhận nhanh"),DC.x("course.drawer.j65",1,"Message us on Zalo"))+'</a>';
