  var pm=["gt","found","hssv","mem","pt"];document.querySelectorAll(".program .program-meta").forEach(function(m,i){var b=document.createElement("button");b.type="button";b.className="cv3-prg-cta";b.dataset.reg=pm[i]||"trial";m.appendChild(b);});
