  document.querySelectorAll(".cv3-prg-cta").forEach(function(b){b.textContent=b.dataset.reg==="pt"?cv3T(DC.x("course.sticky.j3",0,"Liên hệ →"),DC.x("course.sticky.j3",1,"Enquire →")):cv3T(DC.x("course.sticky.j4",0,"Đăng ký →"),DC.x("course.sticky.j4",1,"Sign up →"));});
  var sk=document.getElementById("cv3Sticky");if(sk)sk.innerHTML='<div><small>'+cv3T(DC.x("course.sticky.j5",0,"Foundation 01 · khai giảng {found.start}"),DC.x("course.sticky.j5",1,"Foundation 01 · starts {found.start}"))+'</small>'+cv3T(DC.x("course.sticky.j6",0,"2 lớp · {found.price}đ"),DC.x("course.sticky.j6",1,"2 classes · {found.price}đ"))+'</div><button type="button" data-reg="found" data-pay="deposit">'+cv3T(DC.x("course.sticky.j7",0,"Giữ chỗ"),DC.x("course.sticky.j7",1,"Reserve"))+'</button>';
