function cv3Apply(){document.querySelectorAll(CV3_CASE).forEach(cv3Case);cv3Labels();if(CV3.open){cv3Save();cv3Render();}}
function cv3Sticky(){
  var sk=document.getElementById("cv3Sticky");if(!sk)return;
  var hero=document.querySelector(".phero"),cta=document.querySelector(".cta");
  var past=hero?hero.getBoundingClientRect().bottom<0:scrollY>500;
  var atEnd=cta?cta.getBoundingClientRect().top<innerHeight:false;
  sk.classList.toggle("on",past&&!atEnd&&!CV3.open);
}

var _cv3Apply=applyLang;
applyLang=function(){_cv3Apply();cv3Apply();};

document.addEventListener("click",function(e){
  var r=e.target.closest("[data-reg]");
  if(r){e.preventDefault();cv3Open(r.dataset.reg,{pay:r.dataset.pay,pkg:r.dataset.pkg});return;}
  var sc=e.target.closest("[data-cv3scroll]");
  if(sc){e.preventDefault();var t=document.getElementById(sc.dataset.cv3scroll);if(t){try{t.scrollIntoView({behavior:"smooth",block:"start"});}catch(err){t.scrollIntoView(true);}}return;}
  var a=e.target.closest("[data-cv3]");if(!a)return;
  var act=a.dataset.cv3,v=a.dataset.v;
  if(act==="close"){cv3Close();return;}
  if(act==="prog"){CV3.prog=v;var p=CV3_P[v];CV3.opt=p.opts&&p.opts.length?p.opts[0].id:"";var pl=cv3PayList();CV3.pay=pl[0]?pl[0].id:"";}
  else if(act==="pkg")CV3.pkg=v;
  else if(act==="opt")CV3.opt=v;
  else if(act==="pay"){cv3Save();CV3.pay=v;}
  else if(act==="back"){cv3Save();CV3.step=1;}
  else if(act==="next"){if(CV3.step===1)CV3.step=2;else{cv3Submit();return;}}
  cv3Render();
  if(act==="next"&&CV3.step===2){var n=document.getElementById("cv3Name");if(n&&innerWidth>768)n.focus();}
});
document.getElementById("cv3Ov").addEventListener("click",cv3Close);
document.addEventListener("keydown",function(e){if(e.key==="Escape"&&CV3.open)cv3Close();});
window.addEventListener("scroll",cv3Sticky,{passive:true});
