var CUX_SECS=[["foundation",".foundation-wrap",[DC.x("course.secnav.j1",0,"Foundation"),DC.x("course.secnav.j1",1,"Foundation")]],["programs",".programs",[DC.x("course.secnav.j2",0,"Chương trình"),DC.x("course.secnav.j2",1,"Programs")]],["pricing",".compare",[DC.x("course.secnav.j3",0,"Học phí"),DC.x("course.secnav.j3",1,"Pricing")]],["schedule",".schedule",[DC.x("course.secnav.j4",0,"Lịch tập"),DC.x("course.secnav.j4",1,"Schedule")]],["about",".approach",[DC.x("course.secnav.j5",0,"Về chúng tôi"),DC.x("course.secnav.j5",1,"About")]],["faq",".faq",[DC.x("course.secnav.j6",0,"Hỏi đáp"),DC.x("course.secnav.j6",1,"FAQ")]]];
function cuxOffset(){var n=document.querySelector(".nav"),s=document.getElementById("cuxNav");return (n?n.offsetHeight:0)+(s?s.offsetHeight:0);}
function cuxGo(k){var s=CUX_SECS.filter(function(x){return x[0]===k;})[0];var el=s&&document.querySelector(s[1]);if(!el)return;document.documentElement.style.setProperty("--cux-sm",cuxOffset()+"px");try{el.scrollIntoView({behavior:"smooth",block:"start"});}catch(e){el.scrollIntoView(true);}}
function cuxSpy(){
  var nav=document.getElementById("cuxNav");if(!nav)return;
  var y=cuxOffset()+40,cur=null;
  CUX_SECS.forEach(function(s){var el=document.querySelector(s[1]);if(el&&el.getBoundingClientRect().top<=y)cur=s[0];});
  var hero=document.querySelector(".phero");nav.classList.toggle("stuck",hero?hero.getBoundingClientRect().bottom<=(document.querySelector(".nav")||{offsetHeight:0}).offsetHeight:false);
  nav.querySelectorAll("[data-sec]").forEach(function(a){var on=a.dataset.sec===cur;if(on&&!a.classList.contains("on")){var w=nav.querySelector(".cux-nav-in");if(w)w.scrollTo({left:a.offsetLeft-24,behavior:"smooth"});}a.classList.toggle("on",on);});
}
