  var nav=document.querySelector("#cuxNav .cux-nav-in");
  if(nav)nav.innerHTML=CUX_SECS.map(function(s,i){return '<a href="#" data-sec="'+s[0]+'"><em>0'+(i+1)+'</em>'+cv3L(s[2])+'</a>';}).join("")+'<button type="button" class="cux-nav-cta" data-reg="trial">'+cv3T(DC.x("course.secnav.j7",0,"Học thử miễn phí"),DC.x("course.secnav.j7",1,"Free trial"))+'</button>';
  var hc=document.getElementById("cuxHeroCta");
  if(hc)hc.innerHTML='<a href="#dang-ky" class="cux-hbtn red" data-reg="trial">'+cv3T(DC.x("course.secnav.j8",0,"Đăng ký học thử miễn phí"),DC.x("course.secnav.j8",1,"Book a free trial"))+'</a><a href="#" class="cux-hbtn ghost" data-sec="foundation">'+cv3T(DC.x("course.secnav.j9",0,"Xem lộ trình Foundation"),DC.x("course.secnav.j9",1,"See the Foundation path"))+'</a>';
  var ac=document.getElementById("cuxAboutCta");if(ac)ac.textContent=cv3T(DC.x("course.secnav.j10",0,"Đăng ký buổi tập thử →"),DC.x("course.secnav.j10",1,"Book a trial session →"));
