(function(){
  /* thứ tự: chọn khóa → học phí → lịch tập trước; câu chuyện, không gian, vì sao chọn để sau (trước Hỏi đáp) */
  var faqS=document.querySelector("section.faq"),galS=document.querySelector(".cgallery");galS=galS&&galS.closest("section");
  if(faqS)[document.querySelector("section.approach"),document.querySelector("section.story"),galS,document.querySelector("section.why"),document.querySelector("section.cvideo")].forEach(function(s){if(s)faqS.parentNode.insertBefore(s,faqS);});
  /* hero: thêm 2 nút + đưa dải số liệu vào chân hero */
  var hin=document.querySelector(".phero-inner");
  if(hin){hin.insertAdjacentHTML("beforeend",'<div class="cux-hero-cta" id="cuxHeroCta"></div>');
    var st=document.querySelector(".stats-band .stats-inner");if(st){st.classList.add("cux-hero-stats");hin.appendChild(st);var band=document.querySelector(".stats-band");if(band)band.style.display="none";}}
  /* thanh mục lục ngay dưới hero */
  var hero=document.querySelector(".phero");
  if(hero)hero.insertAdjacentHTML("afterend",'<nav class="cux-nav" id="cuxNav" aria-label="sections"><div class="cux-nav-in"></div></nav>');
  /* cột trái phần "Cách chúng tôi dạy": thêm lối đăng ký */
  var al=document.querySelector(".approach-left");if(al)al.insertAdjacentHTML("beforeend",'<a href="#dang-ky" class="cux-about-cta" id="cuxAboutCta" data-reg="trial"></a>');
  /* lịch tập: mỗi hàng là một lớp có thể bấm để đăng ký */
  var rows={"r-group":function(tr){return ["gt",{opt:/^06/.test(tr.querySelector("th").textContent.trim())?"am":"pm"}];},"r-hssv":function(){return ["hssv",{}];},"r-found":function(tr,i){return ["found",{opt:i===0?"A":"B"}];}};
  var fi=0;
  document.querySelectorAll("table.sched tbody tr").forEach(function(tr){
    var k=Object.keys(rows).filter(function(c){return tr.classList.contains(c);})[0];if(!k)return;
    var r=rows[k](tr,k==="r-found"?fi++:0);tr.classList.add("cux-row");tr.dataset.cuxProg=r[0];if(r[1].opt)tr.dataset.cuxOpt=r[1].opt;tr.tabIndex=0;
  });
  var lg=document.querySelector(".sched-legend");if(lg)lg.insertAdjacentHTML("afterend",'<p class="cux-sched-hint" id="cuxSchedHint"></p>');
  /* FAQ: lối liên hệ khi chưa tìm thấy câu trả lời */
  var fl=document.querySelector(".faq-list");if(fl)fl.insertAdjacentHTML("afterend",'<div class="cux-faq-more" id="cuxFaqMore"></div>');
  document.addEventListener("click",function(e){
    var s=e.target.closest("[data-sec]");if(s){e.preventDefault();cuxGo(s.dataset.sec);return;}
    var tr=e.target.closest("tr.cux-row");if(tr){cv3Open(tr.dataset.cuxProg,{opt:tr.dataset.cuxOpt});}
  });
  document.addEventListener("keydown",function(e){var tr=e.target.closest&&e.target.closest("tr.cux-row");if(tr&&(e.key==="Enter"||e.key===" ")){e.preventDefault();cv3Open(tr.dataset.cuxProg,{opt:tr.dataset.cuxOpt});}});
  window.addEventListener("scroll",cuxSpy,{passive:true});window.addEventListener("resize",cuxSpy);
  var _cux=applyLang;applyLang=function(){_cux();cuxLabels();};
  cuxLabels();
})();

/* ===== COURSE FINAL PASS: lịch tập dạng thẻ trên mobile, bảng giá vuốt ngang, gallery không nhảy trang, CTA ở quy trình đăng ký ===== */
function cfinSched(){
  var heads=[].map.call(document.querySelectorAll("table.sched thead th"),function(th){return th.textContent.trim();});
  document.querySelectorAll("table.sched tbody tr").forEach(function(tr){
    [].forEach.call(tr.children,function(c,i){if(i<2)return;c.dataset.d=heads[i]||"";c.classList.toggle("d-on",!!c.querySelector(".on"));});
    tr.dataset.cta=cv3T(DC.x("course.schedule.j1",0,"Đăng ký →"),DC.x("course.schedule.j1",1,"Sign up →"));
  });
}
function cfinLabels(){
  cfinSched();
  var r=document.getElementById("cfinReg");
  if(r)r.innerHTML='<button type="button" data-reg="found">'+cv3T(DC.x("course.regproc.j1",0,"Bắt đầu đăng ký →"),DC.x("course.regproc.j1",1,"Start signing up →"))+'</button><a href="'+CV3_ZALO+'" target="_blank" rel="noopener">'+cv3T(DC.x("course.regproc.j2",0,"Cần tư vấn trước? Nhắn Zalo"),DC.x("course.regproc.j2",1,"Need advice first? Zalo us"))+'</a>';
  var d=document.getElementById("cfinDots");
  if(d)[].forEach.call(d.children,function(b,i){b.setAttribute("aria-label",cv3T(DC.x("course.regproc.j3",0,"Gói "),DC.x("course.regproc.j3",1,"Plan "))+(i+1));});
}
(function(){
  /* gallery: ảnh không phải link — bỏ href="#" để bấm không bị nhảy về đầu trang */
  document.querySelectorAll(".cgallery a").forEach(function(a){a.removeAttribute("href");});
  /* quy trình đăng ký: thêm lối đăng ký ngay dưới 4 bước */
  var rg=document.querySelector(".reg-grid");if(rg)rg.insertAdjacentHTML("afterend",'<div class="cfin-reg" id="cfinReg"></div>');
  /* bảng giá mobile: vuốt ngang, gói nổi bật đứng đầu, chấm chỉ vị trí */
  var pc=document.querySelector(".compare .pcards");
  if(pc){
    pc.insertAdjacentHTML("afterend",'<div class="cfin-dots" id="cfinDots">'+[0,1,2].map(function(){return '<button type="button"></button>';}).join("")+'</div>');
    var dots=document.getElementById("cfinDots");
    var cards=function(){return [].slice.call(pc.children).sort(function(a,b){return a.offsetLeft-b.offsetLeft;});};
    var upd=function(){var mid=pc.scrollLeft+pc.clientWidth/2,best=0,bd=1e9;cards().forEach(function(c,i){var dd=Math.abs(c.offsetLeft+c.offsetWidth/2-mid);if(dd<bd){bd=dd;best=i;}});[].forEach.call(dots.children,function(b,i){b.classList.toggle("on",i===best);});};
    pc.addEventListener("scroll",upd,{passive:true});window.addEventListener("resize",upd);
    dots.addEventListener("click",function(e){var b=e.target.closest("button");if(!b)return;var c=cards()[[].indexOf.call(dots.children,b)];if(c)pc.scrollTo({left:c.offsetLeft-(pc.clientWidth-c.offsetWidth)/2,behavior:"smooth"});});
    upd();
  }
  var _cfin=applyLang;applyLang=function(){_cfin();cfinLabels();};
  cfinLabels();
})();

